/// Counts the whole wire while retaining at most the configured frame limit.
/// Continuing in count-only mode preserves late serde errors and the exact
/// oversized length previously produced by `serialized_size`, without a second
/// full traversal. No size hints from Serialize are used to reserve memory.
struct BoundedPostcardResponse {
    response: Vec<u8>,
    total: usize,
    limit: usize,
}

impl BoundedPostcardResponse {
    fn new(limit: usize) -> Self {
        let mut response = Vec::with_capacity(limit.min(512));
        if limit >= 8 {
            response.extend_from_slice(&[1, 0, 0, 0, 0, 0, 0, 0]);
        }
        Self {
            response,
            total: 8,
            limit,
        }
    }

    #[inline]
    fn reserve_for(&mut self, required: usize) {
        if required > self.response.capacity() {
            // Vec's usual geometric growth can request capacity beyond limit.
            let capacity = self
                .response
                .capacity()
                .saturating_mul(2)
                .max(required)
                .min(self.limit);
            self.response.reserve_exact(capacity - self.response.len());
        }
    }
}

impl postcard::ser_flavors::Flavor for BoundedPostcardResponse {
    type Output = (Vec<u8>, usize);

    #[inline]
    fn try_push(&mut self, byte: u8) -> postcard::Result<()> {
        self.total = self.total.saturating_add(1);
        if self.total <= self.limit {
            self.reserve_for(self.total);
            self.response.push(byte);
        }
        Ok(())
    }

    #[inline]
    fn try_extend(&mut self, bytes: &[u8]) -> postcard::Result<()> {
        self.total = self.total.saturating_add(bytes.len());
        if self.total <= self.limit {
            self.reserve_for(self.total);
            self.response.extend_from_slice(bytes);
        }
        Ok(())
    }

    fn finalize(self) -> postcard::Result<Self::Output> {
        Ok((self.response, self.total))
    }
}

#[cfg(test)]
mod bounded_postcard_tests {
    use super::BoundedPostcardResponse;
    use postcard::ser_flavors::Flavor;

    #[test]
    fn allocation_stops_at_header_inclusive_limit_and_keeps_counting() {
        for limit in [0, 7, 8, 9, 16, 513, 1025] {
            let mut writer = BoundedPostcardResponse::new(limit);
            for _ in 0..1030 {
                writer.try_push(42).unwrap();
                assert!(writer.response.len() <= limit);
                assert!(writer.response.capacity() <= limit);
            }
            assert_eq!(writer.total, 1038);
        }
    }

    #[test]
    fn oversized_bulk_write_does_not_allocate_from_its_size_hint() {
        let mut writer = BoundedPostcardResponse::new(513);
        writer.try_extend(&[42; 504]).unwrap();
        assert_eq!(writer.response.len(), 512);
        let capacity = writer.response.capacity();
        writer.try_extend(&[42; 8191]).unwrap();
        writer.try_push(42).unwrap();
        assert_eq!(writer.total, 8704);
        assert_eq!(writer.response.len(), 512);
        assert_eq!(writer.response.capacity(), capacity);
    }
}

