use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use std::{collections::BTreeMap, hint::black_box, time::Instant};
include!(concat!(env!("OUT_DIR"), "/production.rs"));
const LIMIT: usize = 1024 * 1024;

// Mechanical balanced makeTree transcription from the unchanged TypeScript fixture.
fn tree(count: usize) -> ParityTree {
    fn append(nodes: &mut Vec<ParityNode>, size: usize) -> usize {
        let id = nodes.len();
        nodes.push(ParityNode {
            id: id as f64,
            name: format!("node-{id}"),
            tag: ["folder", "file", "link"][id % 3].into(),
            note: (id % 2 == 1).then(|| format!("note-{id}")),
            metadata: BTreeMap::from([
                ("owner".into(), format!("owner-{}", id % 7)),
                ("kind".into(), "bench".into()),
            ]),
            children: vec![],
        });
        if size > 1 {
            let left = (size - 1) / 2;
            if left > 0 {
                let child = append(nodes, left);
                nodes[id].children.push(child as f64);
            }
            let child = append(nodes, size - 1 - left);
            nodes[id].children.push(child as f64);
        }
        id
    }
    let mut nodes = Vec::new();
    append(&mut nodes, count);
    ParityTree { nodes }
}

// Baseline corresponds to the original command_into.rs fallback. Candidate uses
// the exact production flavor extracted at build time, not a rewritten flavor.
fn encode<T: Serialize, const CANDIDATE: bool>(
    value: &T,
    target: &mut [u8; 512],
) -> Option<Vec<u8>> {
    target[..8].fill(0);
    target[0] = 1;
    match postcard::to_slice(value, &mut target[8..]) {
        Ok(written) => {
            black_box(written);
            return None;
        }
        Err(postcard::Error::SerializeBufferFull) => {}
        Err(error) => panic!("{error}"),
    }
    let bytes = if CANDIDATE {
        let (bytes, total) =
            postcard::serialize_with_flavor(value, BoundedPostcardResponse::new(LIMIT)).unwrap();
        assert!(total <= LIMIT);
        bytes
    } else {
        let total = 8 + postcard::experimental::serialized_size(value).unwrap();
        assert!(total <= LIMIT);
        let mut bytes = Vec::with_capacity(total);
        bytes.resize(8, 0);
        bytes[0] = 1;
        postcard::to_extend(value, bytes).unwrap()
    };
    Some(bytes)
}
fn batch<T: Serialize, const CANDIDATE: bool>(value: &T, count: usize) -> u128 {
    let mut target = [0; 512];
    let start = Instant::now();
    for _ in 0..count {
        black_box(encode::<T, CANDIDATE>(black_box(value), &mut target));
    }
    start.elapsed().as_nanos()
}
fn measure<T: Serialize>(name: &str, value: &T, count: usize, check_only: bool) {
    let expected = postcard::to_extend(value, vec![1, 0, 0, 0, 0, 0, 0, 0]).unwrap();
    let mut target = [0; 512];
    for candidate in [false, true] {
        let actual = if candidate {
            encode::<T, true>(value, &mut target)
        } else {
            encode::<T, false>(value, &mut target)
        };
        match actual {
            Some(bytes) => assert_eq!(bytes, expected),
            None => assert_eq!(&target[..expected.len()], &expected),
        }
    }
    println!("fixture,{name},frame_bytes,{}", expected.len());
    if check_only {
        return;
    }
    batch::<T, false>(value, 10);
    batch::<T, true>(value, 10);
    for round in 0..6 {
        for candidate in if round % 2 == 0 {
            [false, true]
        } else {
            [true, false]
        } {
            let ns = if candidate {
                batch::<T, true>(value, count)
            } else {
                batch::<T, false>(value, count)
            };
            println!("sample,{name},{round},{candidate},{count},{ns}");
        }
    }
}
fn main() {
    let check_only = std::env::args().any(|arg| arg == "--check-only");
    println!("protocol,rustra-postcard-output-control/v1");
    measure("balanced8191", &tree(8191), 50, check_only);
    measure("small-f64", &42.0f64, 10000, check_only);
}

