use std::{env, fs, path::PathBuf};
fn main() {
    let manifest = PathBuf::from(env::var("CARGO_MANIFEST_DIR").unwrap());
    let root = manifest.ancestors().nth(5).unwrap();
    let command = root.join("crates/rustra/src/command_into.rs");
    let dto = root.join("examples/calculator/src/parity_bench.rs");
    println!("cargo:rerun-if-changed={}", command.display());
    println!("cargo:rerun-if-changed={}", dto.display());
    let command = fs::read_to_string(command).unwrap();
    let flavor = command
        .split_once("struct BoundedPostcardResponse")
        .unwrap()
        .1;
    let flavor = flavor.split("#[cfg(test)]").next().unwrap();
    let dto = fs::read_to_string(dto).unwrap();
    let begin = dto
        .find("#[derive(Debug, Clone, PartialEq, Serialize, Deserialize, JsonSchema)]")
        .unwrap();
    let end = dto
        .find("#[derive(Debug, Serialize, Deserialize, JsonSchema)]")
        .unwrap();
    let out = PathBuf::from(env::var("OUT_DIR").unwrap());
    fs::write(
        out.join("production.rs"),
        format!(
            "struct BoundedPostcardResponse{flavor}\n{}",
            &dto[begin..end]
        ),
    )
    .unwrap();
}
